    char name[20];
    int price;
    int stock;
} Product;

// 商品に値をまとめて入れる(この練習場では { } での初期化が使えないため)
void set(Product *p, char *name, int price, int stock) {
    strcpy(p->name, name);
    p->price = price;
    p->stock = stock;
}

int cheapest(Product items[], int n) {
    int best = 0;
    for (int i = 1; i < n; i++) {
        if (items[i].price < items[best].price) {
            best = i;
        }
    }
    return best;
}

int main() {
    Product items[4];
    set(&items[0], "マウス", 2500, 40);
    set(&items[1], "モニター", 32000, 3);
    set(&items[2], "USBメモリ", 1800, 60);
    set(&items[3], "キーボード", 6800, 8);
    int i = cheapest(items, 4);
    printf("%s\n", items[i].name);
    return 0;
}

